window.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("[data-reveal]").forEach(e=>{e.style.transition="opacity 2s ease, transform 2s ease",new IntersectionObserver(([t],n)=>{t.isIntersecting&&(e.style.opacity="1",e.style.transform="translateY(0)",n.disconnect())}).observe(e)})});